kql.query:
let Window = 3h;
let Signins = SigninLogs | where TimeGenerated > ago(14d);
let FirstSuccess = Signins | where ResultType == "0" | summarize FirstOk = min(TimeGenerated) by UserPrincipalName;
let PrivAccess = Signins
  | where ResultType == "0"
  | where AppDisplayName has_any ("Azure Portal", "Microsoft Azure CLI", "Microsoft Azure PowerShell", "Microsoft Graph", "Windows Azure Service Management API", "Kudu", "SCM")
  | summarize PrivTime = min(TimeGenerated) by UserPrincipalName;
let Failures = Signins | where ResultType != "0" | summarize FailCount = count(), FirstFail = min(TimeGenerated) by UserPrincipalName;
FirstSuccess
| join kind=inner PrivAccess on UserPrincipalName
| join kind=leftouter Failures on UserPrincipalName
| extend ElapsedToPrivilege = PrivTime - coalesce(FirstFail, FirstOk)
| where ElapsedToPrivilege between (0s .. Window)
| project UserPrincipalName, FirstFail, FirstOk, PrivTime, ElapsedToPrivilege, FailCount
| order by ElapsedToPrivilege asc
